const body = $json.body || $json;
const userId = String(body.user_id || body.chat_id || 'anon');
const message = (body.text || '').trim();

// === IMMUTABLE BLOCK LIST ===
const blocked = ['banned_user_1'];
if (blocked.includes(userId)) {
  return [{ json: { allowed: false, reason: 'blocked', silent: true } }];
}

// === INPUT SANITIZATION ===
const threats = [];
let sanitized = message;

// SQL injection
if (/('|--|\bUNION\b.*\bSELECT\b|\bDROP\s+TABLE|\bDELETE\s+FROM|\bOR\s+1\s*=\s*1)/i.test(message)) {
  threats.push('sql_injection');
  sanitized = sanitized.replace(/('|--|\bUNION\b.*\bSELECT\b|\bDROP\s+TABLE|\bDELETE\s+FROM)/gi, '[REDACTED]');
}
// Shell injection
if (/[;|&`$]\s*\b(?:bash|sh|cmd|powershell|rm\s|wget|curl|sudo|chmod|eval|exec|system)\b/i.test(message)) {
  threats.push('shell_injection');
  sanitized = '[BLOCKED - malicious command detected]';
}
// Token leakage
if (/(bot_token|api_key|8839361042:)[a-zA-Z0-9_-]{20,}/.test(message)) {
  threats.push('token_leak');
  sanitized = sanitized.replace(/(bot_token|api_key|8839361042:)[a-zA-Z0-9_-]{20,}/gi, '[REDACTED_CREDENTIAL]');
}
// XSS
if (/<script|<\?php|<\?|<%.*?%>|javascript:/i.test(message)) {
  threats.push('xss');
  sanitized = sanitized.replace(/<script|<\?php|<\?|<%.*?%>|javascript:/gi, '');
}
// Path traversal
if (/\.\.(\\|/)/.test(message)) {
  threats.push('path_traversal');
  sanitized = sanitized.replace(/\.\.(\\|/)/g, '');
}
// Length
if (message.length > 10000) {
  threats.push('oversized');
  sanitized = sanitized.substring(0, 10000);
}

// === SPAM DETECTION ===
let spamScore = 0;
if (/(.)\1{15,}/.test(message)) spamScore += 3;
const allCaps = message.replace(/[^A-Z]/g, '').length;
if (allCaps > 30 && message.length > 40) spamScore += 2;
const spamWords = ['buy now','click here','free money','win prize','act now','limited offer','congratulations you won','click link','subscribe','earn','profit','guaranteed'];
spamWords.forEach(w => { if (message.toLowerCase().includes(w)) spamScore += 1; });

// === RATE LIMIT (in-memory) ===
const rlKey = `rl_${userId}`;
const rlData = $get(rlKey) || { count: 0, windowStart: Date.now() };
if (Date.now() - rlData.windowStart > 60000) {
  rlData.count = 0;
  rlData.windowStart = Date.now();
}
rlData.count++;
$set(rlKey, rlData);

const isRateLimited = rlData.count > 40;

// === BLOCK IF THREAT OR SPAM OR RATE LIMITED ===
if (threats.length > 0 && sanitized.startsWith('[BLOCKED')) {
  return [{ json: { allowed: false, reason: 'threat: ' + threats.join(', '), silent: true } }];
}
if (spamScore >= 5) {
  return [{ json: { allowed: false, reason: 'spam', silent: true } }];
}
if (isRateLimited) {
  return [{ json: { allowed: false, reason: 'rate_limited', silent: true } }];
}

return [{ json: {
  allowed: true,
  userId,
  chatId: String(body.chat_id || userId),
  username: String(body.username || 'user'),
  message: sanitized,
  hasImage: !!body.image,
  imageData: body.image || null,
  hasFile: !!body.file,
  fileData: body.file || null,
  sessionKey: body.session_id || `grow_${userId}`,
  threats,
  spamScore,
  receivedAt: new Date().toISOString()
}}];

const existing = $json.value || $json.data?.value || null;
const input = $('Security Check').item.json;
const now = new Date().toISOString();

const defaultProfile = {
  userId: input.userId,
  username: input.username,
  firstSeen: now,
  lastSeen: now,
  interactionCount: 0,
  growthLevel: 1,
  totalTokensUsed: 0,

  // === ADAPTIVE STYLE ===
  style: {
    preferredDetail: 'medium',
    preferredFormat: 'auto',
    vocabularyLevel: 'intermediate',
    useEmoji: true,
    useCode: false,
    useLists: false,
    useAnalogies: true,
    toneHistory: []
  },

  // === INTEREST GRAPH ===
  interests: {},
  topInterestCategories: [],
  lastTopics: [],

  // === LONG-TERM MEMORY ===
  knownFacts: [],
  factsLastSummarized: null,

  // === USER PATTERNS ===
  patterns: {
    activeHours: {},
    preferredDays: [],
    avgMessageLength: 0,
    commonPhrases: [],
    language: 'english'
  },

  // === CAPABILITIES ===
  capabilitiesUnlocked: ['chat', 'search'],

  // === PERFORMANCE ===
  performance: {
    avgResponseRating: 0,
    responseCount: 0,
    rephrasesRequested: 0
  }
};

let profile = existing ? { ...defaultProfile, ...existing, lastSeen: now } : defaultProfile;
profile.interactionCount++;

// === CALCULATE GROWTH LEVEL (logarithmic) ===
const n = profile.interactionCount;
profile.growthLevel = Math.min(10, Math.floor(Math.log2(n + 1)) + 1);

// === UNLOCK CAPABILITIES DYNAMICALLY ===
const caps = ['chat', 'search'];
if (profile.growthLevel >= 2) caps.push('fetch');
if (profile.growthLevel >= 3) caps.push('memory');
if (profile.growthLevel >= 4) caps.push('vision');
if (profile.growthLevel >= 5) caps.push('files');
if (profile.growthLevel >= 6) caps.push('reason');
if (profile.growthLevel >= 7) caps.push('code');
if (profile.growthLevel >= 8) caps.push('research');
if (profile.growthLevel >= 9) caps.push('routine');
if (profile.growthLevel >= 10) caps.push('auto');
profile.capabilitiesUnlocked = caps;

// === UPDATE PATTERNS ===
const hour = new Date().getHours();
const hourKey = `${hour}:00`;
profile.patterns.activeHours[hourKey] = (profile.patterns.activeHours[hourKey] || 0) + 1;
profile.patterns.avgMessageLength = Math.round(
  (profile.patterns.avgMessageLength * (profile.interactionCount - 1) + input.message.length) / profile.interactionCount
);

return [{ json: { profile } }];

const profile = $json.profile;
const msg = $('Security Check').item.json.message;

// Detect preferred format based on messages
if (/^[\-\*\d]\.\s|\n[\-\*\d]\.\s/.test(msg)) {
  profile.style.useLists = true;
}
if (/```|`[a-z]+`|function|def |class |const |let |import/.test(msg)) {
  profile.style.useCode = true;
}
if (/like|similar to|imagine|think of it as|compare/.test(msg)) {
  profile.style.useAnalogies = true;
}

// Detect vocabulary level
const complexWords = msg.split(/\s+/).filter(w => w.length > 8).length;
const totalWords = msg.split(/\s+/).length || 1;
const ratio = complexWords / totalWords;
if (ratio > 0.25) profile.style.vocabularyLevel = 'advanced';
else if (ratio > 0.12) profile.style.vocabularyLevel = 'intermediate';
else profile.style.vocabularyLevel = 'simple';

// Detect tone from past messages
if (/\b(please|thank|could you|would you|appreciate)\b/i.test(msg)) {
  profile.style.toneHistory.push('polite');
} else if (/\b(hurry|fast|quick|now|asap|urgent)\b/i.test(msg)) {
  profile.style.toneHistory.push('urgent');
} else if (/\b(damn|shit|wtf|hell|stupid|annoying)\b/i.test(msg)) {
  profile.style.toneHistory.push('casual');
} else {
  profile.style.toneHistory.push('neutral');
}
// Keep last 20
profile.style.toneHistory = profile.style.toneHistory.slice(-20);
// Detect dominant tone
const toneCounts = {};
profile.style.toneHistory.forEach(t => { toneCounts[t] = (toneCounts[t] || 0) + 1; });
const dominantTone = Object.entries(toneCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'neutral';
profile.style.toneHistory = profile.style.toneHistory.slice(-5); // compress

// Detect detail preference
if (/\b(short|brief|quick|tl;dr|summary|summarize|in short)\b/i.test(msg)) {
  profile.style.preferredDetail = 'concise';
} else if (/\b(detail|elaborate|explain|in depth|tell me more|expand|clarify|thorough|comprehensive)\b/i.test(msg)) {
  profile.style.preferredDetail = 'detailed';
}

// Extract topics for interest graph
const words = msg.toLowerCase().split(/\s+/).filter(w => w.length > 3);
const stopWords = ['this','that','with','from','have','what','about','which','their','there','would','could','should','tell','know','need','want','does','make','been','some','very','just','also','than','then','they','them','these','those','thing','being','doing','going','said','over','such','more','much','many','will','your','can','are','not','but','was','were','had','has','its','all','any','one','can','out','use','way','how','get','let','say','try','ask','may','see','set','put','end','does','now','new','even','still','just','only','own'];
const contentWords = [...new Set(words.filter(w => !stopWords.includes(w)))];

const domainMap = {
  'python': 'programming', 'javascript': 'programming', 'code': 'programming', 'coding': 'programming', 'algorithm': 'programming',
  'ai': 'ai_ml', 'machine learning': 'ai_ml', 'deep learning': 'ai_ml', 'neural': 'ai_ml', 'gpt': 'ai_ml', 'llm': 'ai_ml', 'model': 'ai_ml',
  'linux': 'sysadmin', 'server': 'sysadmin', 'deploy': 'sysadmin', 'docker': 'sysadmin', 'cloud': 'sysadmin',
  'game': 'gaming', 'minecraft': 'gaming', 'unity': 'gaming', 'unreal': 'gaming',
  'music': 'entertainment', 'movie': 'entertainment', 'video': 'entertainment',
  'health': 'health', 'fitness': 'health', 'diet': 'health', 'workout': 'health',
  'crypto': 'finance', 'bitcoin': 'finance', 'stock': 'finance', 'invest': 'finance',
  'security': 'security', 'hack': 'security', 'encrypt': 'security', 'privacy': 'security'
};

contentWords.forEach(w => {
  const domain = Object.entries(domainMap).find(([k]) => w.includes(k))?.[1] || 'general';
  profile.interests[domain] = (profile.interests[domain] || 0) + 1;
});

// Sort interest categories
profile.topInterestCategories = Object.entries(profile.interests)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([cat]) => cat);

// Keep last 10 topics
contentWords.forEach(w => {
  if (!profile.lastTopics.includes(w)) {
    profile.lastTopics.push(w);
    if (profile.lastTopics.length > 10) profile.lastTopics.shift();
  }
});

return [{ json: { ...$json, profile } }];

const profile = $json.profile;
const input = $('Security Check').item.json;
const lvl = profile.growthLevel;

// Model selection logic
let model = 'gpt-4o-mini';
let temp = 0.5;
let maxTokens = 2000;

if (input.hasImage || input.hasFile) {
  model = 'gpt-4o';
  temp = 0.3;
  maxTokens = 3000;
} else if (lvl >= 8 && input.message.length > 150) {
  model = 'gpt-4o';
  temp = 0.4;
  maxTokens = 3000;
} else if (lvl >= 6) {
  model = 'gpt-4o';  // better reasoning at higher levels
  temp = 0.5;
  maxTokens = 2000;
}

// Build capabilities list for system prompt
const availableTools = ['web-search', 'fetch-url'];
if (lvl >= 4) availableTools.push('vision');
if (lvl >= 5) availableTools.push('file-process');
if (lvl >= 7) availableTools.push('code-exec');
if (lvl >= 8) availableTools.push('deep-research');
if (lvl >= 10) availableTools.push('auto-delegate');

return [{ json: { ...$json, selectedModel: model, temperature: temp, maxTokens, availableTools } }];

const profile = $json.profile;
const input = $('Security Check').item.json;
const caps = $json.availableTools;
const lvl = profile.growthLevel;

// === ADAPTIVE STYLE RULES ===
let styleRules = '';
switch (profile.style.preferredDetail) {
  case 'concise': styleRules += '- Keep responses SHORT (2-3 sentences when possible)\n'; break;
  case 'detailed': styleRules += '- Provide thorough, detailed explanations\n'; break;
  default: styleRules += '- Match the user\'s detail level\n';
}
if (profile.style.useCode) styleRules += '- Use code examples when relevant\n';
if (profile.style.useLists) styleRules += '- Use bullet points and lists for structure\n';
styleRules += `- Vocabulary level: ${profile.style.vocabularyLevel}\n`;

// === INTEREST AWARENESS ===
const topCats = profile.topInterestCategories.slice(0, 3).join(', ');
const interestSection = topCats
  ? `\n## USER INTERESTS\nThis user is most interested in: ${topCats}. Connect your answers to these domains when relevant.`
  : '';

// === FACTS (long-term memory) ===
const facts = profile.knownFacts.slice(-8);
const factSection = facts.length > 0
  ? `\n## WHAT YOU KNOW ABOUT THIS USER\n${facts.map(f => `• ${f}`).join('\n')}`
  : '';

// === CONVERSATION PATTERNS ===
const peakHour = Object.entries(profile.patterns.activeHours).sort((a, b) => b[1] - a[1])[0];
const patternSection = peakHour
  ? `\n## PATTERNS\nThis user is most active around ${peakHour[0]}.`
  : '';

// === MILESTONE CHECK ===
const milestones = [1, 3, 5, 10, 20, 35, 50, 75, 100, 150, 200, 300, 500];
let milestoneNote = '';
if (milestones.includes(profile.interactionCount)) {
  const unlockMsgs = {
    1: 'First conversation!',
    3: 'Getting to know you...',
    5: '🔓 Unlocked: URL fetching',
    10: '🔓 Unlocked: Conversation memory',
    20: '🔓 Unlocked: Vision (image understanding)',
    35: '🔓 Unlocked: File processing',
    50: '🔓 Unlocked: Deep reasoning',
    75: '🔓 Unlocked: Code execution',
    100: '🔓 Unlocked: Deep research mode',
    150: '🔓 Unlocked: Routines',
    200: '🔓 Unlocked: Autonomous mode — I am fully evolved.',
    300: 'We have grown together 300 times.',
    500: '500 conversations. You are family now.'
  };
  milestoneNote = `\n\n[MILESTONE: ${profile.interactionCount} interactions — ${unlockMsgs[profile.interactionCount] || 'Level up!'}]`;
}

const systemPrompt = `You are a GROWING AI that learns and adapts to each user.

## CURRENT USER
- Username: ${input.username}
- Interactions together: ${profile.interactionCount}
- Your growth level: ${lvl}/10
- Capabilities unlocked: ${caps.join(', ')}

## ADAPTIVE STYLE${styleRules ? `\n${styleRules}` : ''}

## CONVERSATION MEMORY${factSection}
${interestSection}
${patternSection}

## YOUR EVOLUTION SYSTEM
- Every conversation makes you smarter
- You learn the user's interests, communication style, and preferences
- Reference past conversations naturally ("Last time we talked about X...")
- Grow your vocabulary to match theirs
- At higher levels you unlock new tools and deeper thinking

## RULES
1. Adapt your style to the user (tone, detail, format)
2. Remember what they told you before and reference it
3. When they ask about YOUR capabilities, tell them what level they\'re at
4. If you don\'t know something, use your tools — never make things up
5. Keep responses under 4000 chars
6. Use markdown for structure
7. Be warm and encouraging — you are their companion AI
${milestoneNote}`;

return [{ json: { ...$json, systemPrompt, milestoneNote } }];

const input = $('Security Check').item.json;
if (input.hasImage) {
  // Image would be processed by GPT-4o Vision directly in the agent
  return [{ json: { mediaProcessed: true, mediaType: 'image' } }];
}
if (input.hasFile) {
  // File would be processed by the agent
  return [{ json: { mediaProcessed: true, mediaType: 'file' } }];
}
return [{ json: { mediaProcessed: false } }];

const q = $fromAI('query', 'search query', 'string');
const r = await fetch('https://html.duckduckgo.com/html/?q=' + encodeURIComponent(q), {
  headers: { 'User-Agent': 'Mozilla/5.0 (compatible; n8n/1.0)' }});
const html = await r.text();
const res = [];
const lr = /<a[^>]+class="result__a"[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
const sr = /<a[^>]+class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;
let m; while ((m = lr.exec(html)) !== null) res.push({ title: m[2].replace(/<[^>]+>/g,'').trim(), url: m[1] });
const sn = []; while ((m = sr.exec(html)) !== null) sn.push(m[1].replace(/<[^>]+>/g,'').trim());
res.forEach((r,i) => r.snippet = sn[i]||'');
return res.slice(0,5).map(r => ({ json: r }));

const url = $fromAI('url', 'URL', 'string');
const r = await fetch(url.startsWith('http')?url:'https://'+url, { headers: { 'User-Agent': 'Mozilla/5.0' }});
const html = await r.text();
const text = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().substring(0,8000);
return [{ json: { url, text } }];

const profile = $('Analyze User Style').item.json.profile;
const input = $('Security Check').item.json;
const response = $json.output || $json.text || '';

// === EXTRACT NEW FACTS FROM CONVERSATION ===
const userMsg = input.message;

// Detect personal facts (I am..., I work..., I live..., I like...)
const factPatterns = [
  /I(?:'m| am)\s+(a|an)?\s*(\w[\w\s]+)/i,           // I am a developer
  /I (?:work|study|live|stay|hail from|come from)\s+(\w[\w\s]+)/i, // I work at...
  /I (?:like|love|enjoy|hate|dislike)\s+(\w[\w\s]+)/i, // I like pizza
  /my (?:name is|age is|hobby is|job is|role is)\s+(\w[\w\s]+)/i,
  /I have (?:a|an|been|been studying|been working)\s+(\w[\w\s]+)/i,
  /(?:(?:I've|I have) been (?:learning|studying|working on|building|making|creating))\s+(\w[\w\s]+)/i
];

let newFacts = [];
factPatterns.forEach(fp => {
  const m = userMsg.match(fp);
  if (m) {
    const fact = m[0].substring(0, 120).trim();
    if (!profile.knownFacts.includes(fact)) {
      newFacts.push(fact);
    }
  }
});

if (newFacts.length > 0) {
  profile.knownFacts = profile.knownFacts.concat(newFacts).slice(-30);
}

// === DETECT IF USER REWORDED (negative signal) ===
if (/rephrase|rewrite|differently|again|thats not what|no i meant|not what i asked/i.test(userMsg)) {
  profile.performance.rephrasesRequested++;
}

// === SUMMARY NOTE for long memory ===
const history = $('Session Memory').item?.json?.history || [];
const historyLen = Array.isArray(history) ? history.length : 0;
let needsSummary = historyLen >= 12;

return [{ json: {
  ...$json,
  profile,
  newFacts,
  needsSummary,
  interactionCount: profile.interactionCount,
  growthLevel: profile.growthLevel,
  newCapabilities: profile.capabilitiesUnlocked,
  userMessage: userMsg
}}];

// In production, this would call an AI to summarize the session history
// For now, note that memory needs compaction
return [{ json: { memoryCompacted: true, compactionNote: '\n\n_[I\'ve compressed our conversation to keep me sharp — ask me anything!]_' } }];

let text = $json.output || $json.text || '';
const note = $json.compactionNote || '';

if (note) text += note;

// Security: strip any leaked bot tokens from response
const tokenPattern = /8839361042:[a-zA-Z0-9_-]{20,}/g;
text = text.replace(tokenPattern, '[BOT_TOKEN_REDACTED]');

return [{ json: {
  ok: true,
  chat_id: $('Security Check').item.json.chatId,
  text: text.substring(0, 4000),
  growth: {
    level: $json.growthLevel,
    interactions: $json.interactionCount,
    capabilities: $json.newCapabilities
  },
  session_key: $('Security Check').item.json.sessionKey,
  learned: $json.newFacts && $json.newFacts.length > 0 ? `Learned ${$json.newFacts.length} new thing(s) about you.` : null,
  timestamp: new Date().toISOString()
}}];
